import { test, expect } from '@playwright/test';

test.describe('Form Autocomplete Attributes', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-page');
  });

  test('should set autocomplete attributes correctly for form fields', async ({ page }) => {
    // Verify autocomplete attribute is set for name field
    const nameInput = page.getByLabel('Full Name');
    await expect(nameInput).toHaveAttribute('autocomplete', 'given-name');

    // Verify autocomplete attribute is set for email field
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toHaveAttribute('autocomplete', 'email');

    // Verify autocomplete attribute is set for phone field
    const phoneInput = page.getByLabel('Phone Number');
    await expect(phoneInput).toHaveAttribute('autocomplete', 'tel');

    // Verify autocomplete attribute is set for address field
    const addressInput = page.getByLabel('Street Address');
    await expect(addressInput).toHaveAttribute('autocomplete', 'street-address');

    // Verify autocomplete attribute is set for zip code field
    const zipInput = page.getByLabel('Zip Code');
    await expect(zipInput).toHaveAttribute('autocomplete', 'postal-code');

    // Verify autocomplete attribute is set for country field
    const countrySelect = page.getByLabel('Country');
    await expect(countrySelect).toHaveAttribute('autocomplete', 'country');

    // Verify autocomplete attribute is set for birthdate field
    const birthdateInput = page.getByLabel('Date of Birth');
    await expect(birthdateInput).toHaveAttribute('autocomplete', 'bd');

    // Verify autocomplete attribute is set for password field
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toHaveAttribute('autocomplete', 'current-password');

    // Verify autocomplete attribute is set for username field
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toHaveAttribute('autocomplete', 'username');
  });

  test('should handle missing autocomplete attributes gracefully', async ({ page }) => {
    // Navigate to a page with missing autocomplete attributes
    await page.goto('/form-page-no-autocomplete');

    // Verify name field exists but lacks autocomplete attribute
    const nameInput = page.getByLabel('Full Name');
    await expect(nameInput).toBeVisible();
    await expect(nameInput).not.toHaveAttribute('autocomplete');

    // Verify email field exists but lacks autocomplete attribute
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();
    await expect(emailInput).not.toHaveAttribute('autocomplete');

    // Verify phone field exists but lacks autocomplete attribute
    const phoneInput = page.getByLabel('Phone Number');
    await expect(phoneInput).toBeVisible();
    await expect(phoneInput).not.toHaveAttribute('autocomplete');

    // Verify form submission still works without autocomplete
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });
});
